def col(fn, name):
    """Spec function that returns one column of a DataFrame-returning metric."""
    def f(c):
        df = fn(c)
        return df[name] if name in df else pd.Series(dtype=float)
    return f


def cols(fn, names):
    def f(c):
        df = fn(c)
        return df[[n for n in names if n in df]]
    return f


def pref(fn, prefix, strip=True):
    def f(c):
        df = fn(c)
        keep = [x for x in df.columns if str(x).startswith(prefix)]
        out = df[keep]
        return out.rename(columns=lambda x: x[len(prefix):]) if strip else out
    return f


